public boolean containsAny(CharSequence cs, String searchChars) {
        if (cs == null || searchChars == null || cs.length() == 0 || searchChars.isEmpty()) {
            return false;
        }

        for (int i = 0; i < cs.length(); i++) {
            if (searchChars.contains(String.valueOf(cs.charAt(i)))) {
                return true;
            }
        }

        return false;
    }

